const healthFiles = [
  {name:'LabHealthComponent.h',content:'#pragma once\n#include "CoreMinimal.h"\n#include "Components/ActorComponent.h"\n#include "LabHealthComponent.generated.h"\nUCLASS(ClassGroup=(Lab), meta=(BlueprintSpawnableComponent))\nclass ENGINELAB_API ULabHealthComponent : public UActorComponent\n{\n    GENERATED_BODY()\npublic:\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category="Health", meta=(ClampMin="1")) float MaxHealth = 100.f;\n    UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category="Health") float Health = 100.f;\nprotected:\n    virtual void BeginPlay() override;\n    UFUNCTION() void ReceiveDamage(AActor* DamagedActor, float Damage, const class UDamageType* Type, class AController* Instigator, AActor* Causer);\n};\n'},
  {name:'LabHealthComponent.cpp',content:'#include "LabHealthComponent.h"\n#include "GameFramework/Actor.h"\nvoid ULabHealthComponent::BeginPlay()\n{\n    Super::BeginPlay();\n    MaxHealth = FMath::Max(1.f, MaxHealth);\n    Health = MaxHealth;\n    GetOwner()->OnTakeAnyDamage.AddDynamic(this, &ULabHealthComponent::ReceiveDamage);\n}\nvoid ULabHealthComponent::ReceiveDamage(AActor* DamagedActor, float Damage, const UDamageType* Type, AController* Instigator, AActor* Causer)\n{\n    if (Damage <= 0.f || Health <= 0.f) return;\n    Health = FMath::Clamp(Health - Damage, 0.f, MaxHealth);\n    UE_LOG(LogTemp, Display, TEXT("%s health: %.0f"), *GetOwner()->GetName(), Health);\n}\n'}
];
const explorerFiles = [
  {name:'ExplorerCharacter.h',content:'#pragma once\n#include "CoreMinimal.h"\n#include "GameFramework/Character.h"\n#include "InputActionValue.h"\n#include "ExplorerCharacter.generated.h"\nclass UInputMappingContext;\nclass UInputAction;\nclass USpringArmComponent;\nclass UCameraComponent;\nUCLASS()\nclass ENGINELAB_API AExplorerCharacter : public ACharacter\n{\n    GENERATED_BODY()\npublic:\n    AExplorerCharacter();\n    virtual void SetupPlayerInputComponent(UInputComponent* PlayerInputComponent) override;\n    UPROPERTY(EditDefaultsOnly, Category="Input") TObjectPtr<UInputMappingContext> MappingContext;\n    UPROPERTY(EditDefaultsOnly, Category="Input") TObjectPtr<UInputAction> MoveAction;\n    UPROPERTY(VisibleAnywhere) TObjectPtr<USpringArmComponent> CameraBoom;\n    UPROPERTY(VisibleAnywhere) TObjectPtr<UCameraComponent> Camera;\nprotected:\n    virtual void BeginPlay() override;\n    void Move(const FInputActionValue& Value);\n};\n'},
  {name:'ExplorerCharacter.cpp',content:'#include "ExplorerCharacter.h"\n#include "EnhancedInputComponent.h"\n#include "EnhancedInputSubsystems.h"\n#include "Engine/LocalPlayer.h"\n#include "GameFramework/PlayerController.h"\n#include "GameFramework/SpringArmComponent.h"\n#include "Camera/CameraComponent.h"\nAExplorerCharacter::AExplorerCharacter()\n{\n    CameraBoom = CreateDefaultSubobject<USpringArmComponent>(TEXT("CameraBoom"));\n    CameraBoom->SetupAttachment(RootComponent);\n    CameraBoom->TargetArmLength = 450.f;\n    CameraBoom->SetRelativeRotation(FRotator(-45.f, 0.f, 0.f));\n    Camera = CreateDefaultSubobject<UCameraComponent>(TEXT("Camera"));\n    Camera->SetupAttachment(CameraBoom);\n}\nvoid AExplorerCharacter::BeginPlay()\n{\n    Super::BeginPlay();\n    if (APlayerController* PC = Cast<APlayerController>(GetController()))\n        if (ULocalPlayer* LP = PC->GetLocalPlayer())\n            if (auto* Subsystem = LP->GetSubsystem<UEnhancedInputLocalPlayerSubsystem>())\n                if (MappingContext) Subsystem->AddMappingContext(MappingContext, 0);\n}\nvoid AExplorerCharacter::SetupPlayerInputComponent(UInputComponent* PlayerInputComponent)\n{\n    Super::SetupPlayerInputComponent(PlayerInputComponent);\n    if (auto* Input = Cast<UEnhancedInputComponent>(PlayerInputComponent))\n        if (MoveAction) Input->BindAction(MoveAction, ETriggerEvent::Triggered, this, &AExplorerCharacter::Move);\n}\nvoid AExplorerCharacter::Move(const FInputActionValue& Value)\n{\n    const FVector2D Axis = Value.Get<FVector2D>();\n    AddMovementInput(FVector::ForwardVector, Axis.Y);\n    AddMovementInput(FVector::RightVector, Axis.X);\n}\n'}
];
const hazardFiles = [
  {name:'LabHazard.h',content:'#pragma once\n#include "CoreMinimal.h"\n#include "GameFramework/Actor.h"\n#include "LabHazard.generated.h"\nclass USphereComponent;\nUCLASS()\nclass ENGINELAB_API ALabHazard : public AActor\n{\n    GENERATED_BODY()\npublic:\n    ALabHazard();\n    UPROPERTY(VisibleAnywhere) TObjectPtr<USphereComponent> Trigger;\n    UPROPERTY(EditAnywhere, Category="Damage") float Damage = 25.f;\nprotected:\n    virtual void BeginPlay() override;\n    UFUNCTION() void OnOverlap(UPrimitiveComponent* Overlapped, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 BodyIndex, bool bFromSweep, const FHitResult& Hit);\n};\n'},
  {name:'LabHazard.cpp',content:'#include "LabHazard.h"\n#include "Components/SphereComponent.h"\n#include "GameFramework/Pawn.h"\n#include "Kismet/GameplayStatics.h"\nALabHazard::ALabHazard()\n{\n    Trigger = CreateDefaultSubobject<USphereComponent>(TEXT("Trigger"));\n    SetRootComponent(Trigger);\n    Trigger->InitSphereRadius(100.f);\n    Trigger->SetCollisionProfileName(TEXT("OverlapAllDynamic"));\n    Trigger->SetGenerateOverlapEvents(true);\n}\nvoid ALabHazard::BeginPlay()\n{\n    Super::BeginPlay();\n    Trigger->OnComponentBeginOverlap.AddDynamic(this, &ALabHazard::OnOverlap);\n}\nvoid ALabHazard::OnOverlap(UPrimitiveComponent* Overlapped, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 BodyIndex, bool bFromSweep, const FHitResult& Hit)\n{\n    if (!IsValid(OtherActor) || OtherActor == this || !OtherActor->IsA<APawn>()) return;\n    UGameplayStatics::ApplyDamage(OtherActor, FMath::Max(0.f, Damage), GetInstigatorController(), this, nullptr);\n    UE_LOG(LogTemp, Display, TEXT("Hazard hit: %s"), *OtherActor->GetName());\n    SetActorEnableCollision(false);\n    Destroy();\n}\n'}
];
const scoreFiles = [
  {name:'LabScoreComponent.h',content:'#pragma once\n#include "CoreMinimal.h"\n#include "Components/ActorComponent.h"\n#include "LabScoreComponent.generated.h"\nUCLASS(ClassGroup=(Lab), meta=(BlueprintSpawnableComponent))\nclass ENGINELAB_API ULabScoreComponent : public UActorComponent\n{\n    GENERATED_BODY()\npublic:\n    UPROPERTY(VisibleAnywhere, BlueprintReadOnly, Category="Score") int32 Score = 0;\n    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category="Score", meta=(ClampMin="1")) int32 Goal = 3;\n    UFUNCTION(BlueprintCallable) void AddPoint();\n};\n'},
  {name:'LabScoreComponent.cpp',content:'#include "LabScoreComponent.h"\nvoid ULabScoreComponent::AddPoint()\n{\n    if (Score >= Goal) return;\n    ++Score;\n    UE_LOG(LogTemp, Display, TEXT("Score: %d / %d"), Score, Goal);\n    if (Score >= Goal) UE_LOG(LogTemp, Display, TEXT("Level complete!"));\n}\n'},
  {name:'LabPickup.h',content:'#pragma once\n#include "CoreMinimal.h"\n#include "GameFramework/Actor.h"\n#include "LabPickup.generated.h"\nclass USphereComponent;\nclass UStaticMeshComponent;\nUCLASS()\nclass ENGINELAB_API ALabPickup : public AActor\n{\n    GENERATED_BODY()\npublic:\n    ALabPickup();\n    UPROPERTY(VisibleAnywhere) TObjectPtr<USphereComponent> Trigger;\n    UPROPERTY(VisibleAnywhere) TObjectPtr<UStaticMeshComponent> Mesh;\nprotected:\n    virtual void BeginPlay() override;\n    UFUNCTION() void OnOverlap(UPrimitiveComponent* Overlapped, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 BodyIndex, bool bFromSweep, const FHitResult& Hit);\n};\n'},
  {name:'LabPickup.cpp',content:'#include "LabPickup.h"\n#include "LabScoreComponent.h"\n#include "Components/SphereComponent.h"\n#include "Components/StaticMeshComponent.h"\nALabPickup::ALabPickup()\n{\n    Trigger = CreateDefaultSubobject<USphereComponent>(TEXT("Trigger"));\n    SetRootComponent(Trigger);\n    Trigger->InitSphereRadius(75.f);\n    Trigger->SetCollisionProfileName(TEXT("OverlapAllDynamic"));\n    Mesh = CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Mesh"));\n    Mesh->SetupAttachment(Trigger);\n    Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);\n}\nvoid ALabPickup::BeginPlay()\n{\n    Super::BeginPlay();\n    Trigger->OnComponentBeginOverlap.AddDynamic(this, &ALabPickup::OnOverlap);\n}\nvoid ALabPickup::OnOverlap(UPrimitiveComponent* Overlapped, AActor* OtherActor, UPrimitiveComponent* OtherComp, int32 BodyIndex, bool bFromSweep, const FHitResult& Hit)\n{\n    if (!IsValid(OtherActor)) return;\n    if (auto* Score = OtherActor->FindComponentByClass<ULabScoreComponent>())\n    {\n        SetActorEnableCollision(false);\n        Score->AddPoint();\n        Destroy();\n    }\n}\n'}
];
const ueSetup = '目标：UE 5.6 桌面项目（Windows），项目名称固定 EngineLab。示例为学习源码，未在本机UE编辑器编译验证。\n\n1. 安装UE 5.6及其对应MSVC/Windows SDK工具链，VS Code负责编辑，Unreal Build Tool负责构建；不要用g++直接编译UE源码。\n2. 创建Games → Blank → C++项目，命名EngineLab。首次关闭编辑器后复制本包.h/.cpp到Source/EngineLab/，保留项目原有模块文件。\n3. .generated.h必须是本头文件最后一条include。项目若使用其他名称，修改ENGINELAB_API为实际模块导出宏。\n4. 生成/刷新VS Code工程文件，用Development Editor Win64目标构建，再打开编辑器。修改反射声明后建议关闭编辑器完整构建，避免旧反射状态。\n5. 对照本课步骤创建蓝图和输入资产，这些二进制资产不能只靠本包C++文件替代。\n6. 验收使用Play模式与Output Log，保存关卡和资产到同一Git仓库；大型资产需另行评估Git LFS。\n';
function ueData(data) {
  return { ...data, toolchain: 'UE 5.6 · 未在本机编译验证', setup: ueSetup + '\n本课操作：\n' + data.tasks.map((t,i)=>`${i+1}. ${t}`).join('\n'),
    starterFiles: data.files.map(f => f.name.endsWith('.cpp') ? {name:f.name,content:`#include "${f.name.replace('.cpp','.h')}"\n// TODO: 按头文件逐个实现函数；先阅读本课项目配置步骤。\n`} : f),
    sources: [
      ['Epic · C++ Quick Start','https://dev.epicgames.com/documentation/en-us/unreal-engine/unreal-engine-cpp-quick-start?application_version=5.6'],
      ['Epic · VS Code 配置','https://dev.epicgames.com/documentation/en-us/unreal-engine/setting-up-visual-studio-code-for-unreal-engine?application_version=5.6'],
      ['Epic · Enhanced Input','https://dev.epicgames.com/documentation/en-us/unreal-engine/enhanced-input-in-unreal-engine?application_version=5.6']
    ] };
}

