  frames: [['构造', [['Actor', 'MovingMarker'], ['Root', 'StaticMeshComponent'], ['Tick开关', 'true']], '默认子对象在构造中建立。'], ['每帧更新', [['Speed', '50 cm/s'], ['DeltaTime', '示例0.02s'], ['位移', '1 cm']], '时间步是本次更新的秒数。'], ['世界位置', [['原位置', '(0,0,0)'], ['更新后', '(1,0,0)'], ['坐标空间', 'World']], 'AddActorWorldOffset使用世界空间位移。']], rule: '构造建立结构，BeginPlay准备运行，Tick推进状态。', example: 'AddActorWorldOffset(FVector(Speed * DeltaTime,0,0));', trap: 'Actor构造可能在编辑器发生，不代表玩家刚进入游戏。',
