const l29 = make(29, '反射、属性与蓝图交互', '让生命值成为可复用组件', ueData({
  scene: '把生命值从某个特定角色里提出来，作为可以挂到不同Actor上的组件，并向蓝图公开合适的读取接口。', kind:'object', objectives: ['使用UPROPERTY/UFUNCTION', '区分编辑与运行数据', '认识UE对象管理'],
  sections: [['反射的作用', 'UPROPERTY与UFUNCTION让引擎了解字段和函数，用于编辑器、蓝图、序列化等。它们不只是给IDE看的注释，也不是替代C++访问控制的通行证。'], ['配置与状态分开', 'MaxHealth用EditAnywhere允许配置，Health用VisibleAnywhere/BlueprintReadOnly展示运行状态。编辑器ClampMin提高输入体验，运行时代码仍要校验，不能只依赖编辑器元数据。'], ['组件生命周期', 'BeginPlay中初始化生命值并订阅Owner的OnTakeAnyDamage。伤害委托签名必须匹配，绑定目标使用UFUNCTION以接入动态委托。'], ['UE对象不是普通unique_ptr资源', 'UObject体系由引擎管理，使用反射可见引用与适合的TObjectPtr等类型；不要对Actor或组件随意使用delete或用std::unique_ptr接管。Destroy和垃圾回收也不是同一个即时动作。']],
  files: healthFiles, tasks: ['编译LabHealthComponent，在任意Actor蓝图中Add Component添加它。', '将MaxHealth设120，Play确认Health初始化为120。', '蓝图使用Apply Damage对该Actor施加25伤害，Output Log应显示95；负伤害不改变状态。'], challenge: '增加OnHealthChanged动态多播委托，让蓝图UI订阅生命值变化。', expected: 'MaxHealth=120，Apply Damage=25 → health: 95\n超量伤害 → health: 0\n无效的非正伤害忽略。',
  frames: [['配置', [['蓝图属性', 'MaxHealth=120'], ['编辑元数据', 'ClampMin=1'], ['运行检查', '仍然必须做']], '编辑便利与运行时校验是两层职责。'], ['初始化', [['Owner Actor', '拥有组件'], ['Health', '120'], ['委托订阅', 'OnTakeAnyDamage']], '组件挂接到所属Actor的事件。'], ['伤害事件', [['Damage', '25'], ['Health', '120→95'], ['BlueprintReadOnly', '可读状态']], '伤害经过接口，组件维护范围。']], rule: '配置可编辑，状态受规则约束，通过接口连接蓝图。', example: 'UPROPERTY(VisibleAnywhere, BlueprintReadOnly)', trap: '不要对引擎管理的UObject使用普通delete。',
  questions: [['UPROPERTY是否等于public？', '不是。反射说明与C++访问控制是不同机制，还需配置编辑器和蓝图暴露范围。'], ['为什么ClampMin仍不足以保护状态？', '它主要服务编辑器输入，代码或外部数据仍可能提供无效值，运行时需要校验。'], ['UObject与普通C++对象生命周期有何不同？', 'UObject参与引擎对象与垃圾回收体系，引用、创建和销毁遵循引擎约定。']]
}));

const l30 = make(30, '输入、角色与移动', '把按键变成角色行动', ueData({
  scene: '从键盘WASD到Input Action，再到CharacterMovement。输入描述意图，角色和移动组件负责把意图变成运动。', kind:'flow', objectives: ['配置Enhanced Input', '区分Pawn与Controller', '使用AddMovementInput'],
  sections: [['输入需要被控制的Pawn', 'Character是一种带移动能力的Pawn；PlayerController控制Pawn。仅把角色放到关卡不一定会收到输入，需要默认Pawn设置或Auto Possess Player等配置。'], ['动作与映射分离', 'Input Action表达Move这样的意图，Mapping Context把WASD等硬件输入映射到动作。IA_Move设Axis2D，按键默认进入X轴，W/S需要Swizzle到Y，S/A需要Negate。'], ['接入Enhanced Input', '在模块Build.cs的依赖中加入EnhancedInput，确认插件启用。BeginPlay为本地玩家添加Mapping Context；SetupPlayerInputComponent把动作绑定到Move。'], ['角色移动不是直接位移', 'AddMovementInput向移动组件提供方向与强度，CharacterMovement处理速度和碰撞等。不要再给这种输入强度随意乘DeltaTime；这与Tick里直接更新位置的接口语义不同。']],
  files: explorerFiles, tasks: ['EngineLab.Build.cs依赖加入EnhancedInput；启用插件后完整构建。', '创建IA_Move（Axis2D）和IMC_Player：D=+X，A=Negate X，W=Swizzle YXZ，S=Negate后Swizzle YXZ。', '创建BP_Explorer，配置MappingContext和MoveAction；添加可见网格，放到带地面关卡，Auto Possess Player设Player0。', 'Play后WASD移动，检查相机、碰撞和角色控制；CharacterMovement的MaxWalkSpeed可设400。'], challenge: '增加鼠标视角动作，让移动方向根据Controller朝向计算。', expected: 'W/S沿世界X正负移动，A/D沿世界Y负正移动；释放按键后停止输入。\n本课相机固定俯视方向，不包含鼠标旋转。',
  frames: [['硬件', [['W', '映射到+Y轴值'], ['IA_Move', '(0,1)'], ['IMC_Player', '本地玩家已添加']], '动作坐标是输入向量，不直接等于世界坐标。'], ['绑定', [['EnhancedInputComponent', 'Triggered'], ['Move(Value)', '读取FVector2D'], ['角色', '被Player0控制']], '动作触发后才进入对应C++处理函数。'], ['移动', [['Axis.Y', '世界Forward'], ['Axis.X', '世界Right'], ['CharacterMovement', '执行运动']], '交给移动组件处理，不重复乘dt。']], rule: '映射描述按键，动作表达意图，移动组件处理运动。', example: 'AddMovementInput(FVector::ForwardVector, Axis.Y);', trap: '创建Input Action并不等于已把Mapping Context加入本地玩家。',
  questions: [['Pawn与Controller的职责？', 'Pawn表示可被控制的世界实体，Controller负责控制意图与拥有关系；Character是带常用移动能力的Pawn。'], ['为什么移动没反应？', '检查Possess、输入组件类型、Mapping Context是否添加、动作资产是否赋值及映射修饰符。'], ['AddMovementInput为何不直接乘dt？', '它提供意图和强度，移动组件按自身时间更新；直接位移接口才需要显式计算速度乘时间。']]
}));

const l31 = make(31, '碰撞、重叠与伤害事件', '从相遇到状态变化', ueData({
  scene: '放置一次性伤害区域，角色进入后受到25伤害。触发器、伤害事件和生命值组件各自承担一段流程。', kind:'flow', objectives: ['区分Overlap与Block', '绑定重叠委托', '通过事件施加伤害'],
  sections: [['Overlap不是Block', 'Block用于阻挡并可能产生Hit，Overlap用于相交感知。双方组件的碰撞启用、对象通道响应和GenerateOverlapEvents都影响事件是否发生。'], ['委托签名必须一致', 'OnComponentBeginOverlap的参数含重叠组件、其他Actor和Sweep信息。动态绑定要求接收函数具有匹配签名并被UFUNCTION声明。'], ['伤害与生命值解耦', 'UGameplayStatics::ApplyDamage发送通用伤害流程，不会凭空修改你自定义的Health变量。目标需要第29课的生命值组件或自己的伤害处理逻辑。'], ['一次性触发', '进入后先施加伤害，再关闭自身碰撞并Destroy，避免多个组件重叠造成重复命中。实际项目可增加无敌帧、目标过滤和联网权威校验。']],
  files: [...hazardFiles,...healthFiles], tasks: ['加入LabHazard与LabHealthComponent源码并构建。', '把Health组件挂到玩家蓝图；放置LabHazard到角色路径，编辑器中查看触发球范围。', '确认玩家胶囊启用Query碰撞并生成Overlap；进入触发球，检查100→75且触发器销毁。'], challenge: '将触发器改为持续伤害，使用Timer并在离开区域时停止，处理重复进入。', expected: '玩家第一次进入：Hazard hit日志，Health100→75。\n同一个Hazard不再重复伤害；无Health组件时只有伤害事件，没有自定义扣血。',
  frames: [['相遇', [['玩家胶囊', 'Pawn'], ['触发球', 'OverlapAllDynamic'], ['前提', '双方碰撞配置正确']], '图示是事件流程，实际通道必须在编辑器核对。'], ['发送事件', [['OnOverlap', '过滤有效Pawn'], ['ApplyDamage', '25'], ['目标Actor', '收到伤害']], '碰撞对象不直接访问目标的private生命值。'], ['目标处理', [['Health组件', '100→75'], ['触发器', '关闭碰撞'], ['Destroy', '请求销毁Actor']], '状态改变由目标接收逻辑完成。']], rule: '碰撞发现相遇，事件传递意图，目标维护状态。', example: 'UGameplayStatics::ApplyDamage(Target,25.f,...);', trap: 'ApplyDamage不会自动替你创建或修改Health字段。',
  questions: [['Overlap与Hit有什么区别？', 'Overlap用于相交感知，Hit常用于阻挡碰撞接触；事件产生还依赖双方组件与通道配置。'], ['事件为何完全不触发？', '检查Query碰撞、响应通道、GenerateOverlapEvents、实例位置和委托绑定，而不是只看C++函数体。'], ['为什么命中后先关碰撞？', '避免等待销毁期间其他组件再次触发事件而重复计算伤害。']]
}));

